        date: row[COL.date - 1] || "",
        address: row[COL.address - 1] || "",
        phone: row[COL.phone - 1] || "",
        cod: row[COL.cod - 1] || 0,
        product: row[COL.productName - 1] || "",
        customer: row[COL.customerName - 1] || "",
        selected_product: row[COL.selectedProduct - 1] || "No Sellect",
